(()=>{'use strict';const all=window.CATALOG;let topic='',limit=24;const q=document.querySelector('#search'),results=document.querySelector('#results');const names={T1:'材料生成与逆向设计',T2:'合成与工艺',T3:'自主实验闭环',T4:'性质、表征与材料表示',T5:'电子结构学习',T6:'机器学习势训练与泛化',T7:'采样与高性能原子模拟',T8:'智能体技术与科研系统'};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const terms=q.value.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);const selected=all.filter(p=>(!topic||p.topic===topic)&&terms.every(t=>p.search.toLocaleLowerCase().includes(t)));const sort=document.querySelector('#sort').value;selected.sort(sort==='title'?(a,b)=>a.title.localeCompare(b.title,'zh-CN'):sort==='old'?(a,b)=>a.date.localeCompare(b.date):(a,b)=>b.date.localeCompare(a.date));document.querySelector('#result-count').textContent=`${selected.length} 篇${topic?' · '+names[topic]:''}`;results.innerHTML=selected.slice(0,limit).map(p=>`<a class="card" href="${p.url}"><div class="card-meta"><span>${p.topic} / ${esc(p.topicName)}</span><time>${p.date}</time></div><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}${p.excerpt.length===160?'…':''}</p><div class="card-bottom"><span>阅读全文</span><span>↗</span></div></a>`).join('')||'<div class="empty">没有找到匹配的文献，试试其他关键词。</div>';document.querySelector('#more').hidden=selected.length<=limit;}const topics=document.querySelector('#topics');for(const [id,name] of [['','全部话题'],...Object.entries(names)]){const b=document.createElement('button');b.textContent=name;b.type='button';b.dataset.topic=id;b.setAttribute('aria-pressed',String(id===''));b.onclick=()=>{topic=id;limit=24;topics.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();};topics.append(b);}q.addEventListener('input',()=>{limit=24;render();});document.querySelector('#sort').onchange=()=>{limit=24;render();};document.querySelector('#more').onclick=()=>{limit+=24;render();};render();})();
